            <div className="flex items-center gap-2.5">
              <Settings className="size-4 text-muted-foreground group-hover:text-foreground" />
              <span className="font-medium">Agent settings…</span>
            </div>
          </button>
        ) : null}
      </div>
    </div>
  );

